    { lz: 'n1', q: 'Womit wurde Napoleon 1793 zum ersten Mal bekannt?', o: ['Er lenkte bei Toulon das Feuer der Kanonen und zwang die Engländer zum Abzug.', 'Er wurde zum Kaiser gekrönt.', 'Er eroberte Moskau.'], e: 'Als junger Hauptmann fiel er bei der Belagerung von Toulon auf. Danach wurde er zum General befördert.' },
    { lz: 'n1', q: 'Wie wurde Napoleon 1799 Herrscher über Frankreich?', o: ['Er kehrte aus Ägypten zurück und stürzte die Regierung, das Direktorium.', 'Er wurde vom König zum Nachfolger bestimmt.', 'Er gewann eine freie Wahl gegen den König.'], e: 'Der ehrgeizige General nutzte seinen Ruhm aus Ägypten für einen Staatsstreich. Eine neue Verfassung machte ihn zum Ersten Konsul.' },
    { lz: 'n1', q: 'Was geschah 1802?', o: ['Napoleon wurde Konsul auf Lebenszeit.', 'Napoleon wurde zum Kaiser gekrönt.', 'Napoleon wurde in Russland besiegt.'], e: 'Er liess das Volk abstimmen, damit seine Herrschaft rechtmässig erscheint. 1802 wurde er Konsul auf Lebenszeit, 1804 Kaiser.' },
    { lz: 'n1', q: 'Was geschah am 2. Dezember 1804?', o: ['Napoleon krönte sich selbst zum Kaiser der Franzosen.', 'Napoleon wurde Erster Konsul.', 'Der Wiener Kongress begann.'], e: 'Er krönte zuerst sich selbst, dann seine Frau Joséphine. Papst Pius VII. hatte das Paar zuvor gesalbt.' },
    { lz: 'n1', q: 'Was wurde Napoleon 1812 zum Verhängnis?', o: ['Der Feldzug nach Russland', 'Der Feldzug nach Ägypten', 'Die Kontinentalsperre gegen Spanien'], e: 'Von 600 000 Soldaten überlebten nur rund 100 000. 1814 musste er den Kaisertitel abgeben, 1815 wurde er endgültig besiegt.' },
    { lz: 'n2', q: 'Was ist der Code civil?', o: ['Ein Gesetzbuch, das die Rechte der Personen, der Güter und des Eigentums in Frankreich festlegte', 'Die Verfassung der Helvetischen Republik', 'Ein Vertrag zwischen Napoleon und dem Papst'], e: 'Der Code civil entstand 1804 unter Napoleon. Er war lange das fortschrittlichste Gesetzbuch überhaupt.' },
    { lz: 'n2', q: 'Welche Bestimmung des Code civil von 1804 würde man heute kritisieren?', o: ['Die Frau schuldet ihrem Mann Gehorsam.', 'Niemand muss sein Eigentum ohne Entschädigung abgeben.', 'Für alle gilt das gleiche Recht.'], e: 'Artikel 213 und 373 benachteiligen die Frau: Gehorsam gegenüber dem Mann, elterliche Gewalt nur für den Vater. Aus heutiger Sicht verletzt das die Gleichberechtigung.' },
    { lz: 'n2', q: 'Warum gründete Napoleon staatliche Gymnasien und Universitäten?', o: ['Um fähige junge Leute für Verwaltung und Militär heranzuziehen', 'Um die Kirche zu stärken', 'Damit die Zeitungen frei berichten konnten'], e: 'Er brauchte gut ausgebildete Leute für seinen zentralisierten Staat und seine Armee.' },
    { lz: 'n2', q: 'Warum nennt man Napoleons Herrschaft auch eine Militärdiktatur?', o: ['Seine wirkliche Macht war das Militär, und es gab keine Freiheit für Presse und Volk.', 'Weil nur Soldaten abstimmen durften', 'Weil er nie Gesetze erliess'], e: 'Zeitungen durften nicht frei berichten, Spitzel der Polizei überwachten das Volk. Napoleons Macht beruhte auf dem Militär und auf seinen Siegen.' },
    { lz: 'n3', q: 'Wer schloss sich 1803 im Krieg gegen Frankreich England an?', o: ['Russland und Österreich', 'Spanien und Neapel', 'Die Schweiz und Preussen'], e: 'England duldete Frankreichs Vorherrschaft auf dem Kontinent nicht. 1805 besiegte Napoleon Österreich und Russland, 1806 Preussen.' },
    { lz: 'n3', q: 'Warum griff Napoleon England nicht direkt an?', o: ['Die englische Flotte war stärker als die französische.', 'England war mit ihm verbündet.', 'England war neutral.'], e: 'Weil er England auf dem Meer nicht schlagen konnte, wandte er sich gegen Österreich und Russland und verhängte 1806 die Kontinentalsperre.' },
    { lz: 'n3', q: 'Was war das Ziel der Neuordnung Europas durch Napoleon?', o: ['Die Vorherrschaft Frankreichs zu sichern', 'Alle Länder zu Demokratien zu machen', 'Ein Gleichgewicht der Grossmächte herzustellen'], e: 'Machtzentrum war das bis zum Rhein vergrösserte Kaiserreich Frankreich. Ringsherum lagen abhängige Staaten. Das Gleichgewicht der Mächte war erst das Ziel des Wiener Kongresses.' },
    { lz: 'n3', q: 'Wie weit reichte Napoleons Macht 1808?', o: ['Von Gibraltar bis nach Russland', 'Von Paris bis an den Rhein', 'Nur über Frankreich und die Schweiz'], e: '1808 brachte er auch Spanien unter seine Kontrolle. Damit hatte er alle Grossmächte auf dem Kontinent besiegt.' },
    { lz: 'n4', q: 'Was war die Kontinentalsperre (1806)?', o: ['Kein Land unter Napoleons Herrschaft durfte mit England Handel treiben.', 'Eine Mauer an der Grenze Frankreichs', 'Ein Verbot, nach Amerika auszuwandern'], e: 'Napoleon wollte England wirtschaftlich in die Knie zwingen, weil er es militärisch nicht direkt angreifen konnte.' },
    { lz: 'n4', q: 'Was war der Rheinbund?', o: ['Ein Bund süd- und westdeutscher Fürsten mit Napoleon als Schutzherrn', 'Ein Bündnis von England, Russland und Österreich', 'Der Bund der Kantone nach 1815'], e: 'Die Fürsten gründeten ihn auf Napoleons Wunsch. Sie mussten ihm im Kriegsfall Soldaten stellen.' },
    { lz: 'n4', q: 'Wie regierte Napoleon zum Beispiel Spanien, Neapel und Westfalen?', o: ['Er setzte Verwandte als Herrscher ein.', 'Er liess dort freie Wahlen abhalten.', 'Er machte sie zu Kantonen der Schweiz.'], e: 'Verwandte auf den Thronen sicherten ihm die Kontrolle über diese Länder.' },
    { lz: 'n4', q: 'Wozu schuf Napoleon 1807 das Grossherzogtum Warschau?', o: ['Als verlässliche Stütze im Osten', 'Als neue Hauptstadt Frankreichs', 'Als Geschenk an den Zaren'], e: 'Er schuf es aus Teilen der Länder seiner Gegner, vor allem Preussens.' }
